def _same_instant(left: str, right: str) -> bool:
    if "T" not in left or "T" not in right:
        return left == right
    return datetime.fromisoformat(left.replace("Z", "+00:00")) == datetime.fromisoformat(
        right.replace("Z", "+00:00")
    )

