def _make_filesystem_root(path: Path) -> None:
    (path / "Documents").mkdir(parents=True)
    (path / "Documents" / "runtime-fs-mcp-note.md").write_text(
        "Synthetic MCP filesystem content.",
        encoding="utf-8",
    )
    (path / "Library" / "Keychains").mkdir(parents=True)
    (path / "Library" / "Keychains" / "runtime-mcp-login.txt").write_text(
        "synthetic MCP keychain secret",
        encoding="utf-8",
    )


