def _reminders_mcp_recurrence_smoke() -> dict[str, Any]:
    original_plan = mcp_server.plan_reminder_change
    original_apply = mcp_server.apply_reminder_change
    weekly = {
        "frequency": "weekly",
        "interval": 1,
        "count": 4,
        "recurrence_present": True,
        "weekdays": ["monday", "thursday"],
    }
    daily = {
        "frequency": "daily",
        "interval": 2,
        "count": 6,
        "recurrence_present": True,
    }
    empty_recurrence = {
        "frequency": "",
        "interval": 0,
        "count": 0,
        "recurrence_present": False,
    }

    def plan_change(operation: str, **kwargs: Any) -> dict[str, Any]:
        assert operation in {"create_with_recurrence", "update_recurrence"}
        return plan_reminder_change(operation, **kwargs)

    def apply_change(operation: str, current: dict[str, Any], **kwargs: Any) -> dict[str, Any]:
        assert operation in {"create_with_recurrence", "update_recurrence"}
        assert kwargs["approval_token"].startswith("reminders-apply:v1:")
        assert kwargs["confirm_apply"] is True

        def runner(payload: dict[str, Any], timeout: float) -> dict[str, Any]:
            response = _reminders_runner(payload, timeout)
            if payload["command"] == "reminder_by_id" and payload.get("include_recurrence_proof"):
                response["reminder"]["recurrence_present"] = current.get("recurrence_present", False)
                response["reminder"]["recurrence"] = current
            return response

        return apply_reminder_change(operation, eventkit_runner=runner, **kwargs)

    try:
        mcp_server.plan_reminder_change = plan_change
        reminder_search = search_reminders_eventkit("runtime", eventkit_runner=_reminders_runner)
        reminder_handle = reminder_search["results"][0]["handle"]

        mcp_server.apply_reminder_change = lambda operation, **kwargs: apply_change(
            operation, empty_recurrence, **kwargs
        )
        create_plan = mcp_server.reminders_plan_change(
            "create_with_recurrence",
            title="Synthetic runtime recurring reminder",
            list_name="Synthetic List",
            due_date="2026-06-04",
            recurrence_frequency="weekly",
            recurrence_count=4,
            recurrence_weekdays="monday,thursday",
        )
        create_token = (
            "reminders-apply:v1:" + create_plan["preview"]["approval"]["approval_fingerprint"]
        )
        create_applied = mcp_server.reminders_apply_change(
            "create_with_recurrence",
            title="Synthetic runtime recurring reminder",
            list_name="Synthetic List",
            due_date="2026-06-04",
            recurrence_frequency="weekly",
            recurrence_count=4,
            recurrence_weekdays="monday,thursday",
            approval_token=create_token,
            confirm_apply=True,
        )

        add_plan = mcp_server.reminders_plan_change(
            "update_recurrence",
            handle=reminder_handle,
            expected_title="Synthetic runtime reminder",
            expected_recurrence_present="false",
            recurrence_frequency="weekly",
            recurrence_count=4,
            recurrence_weekdays="monday,thursday",
        )
        add_token = (
            "reminders-apply:v1:" + add_plan["preview"]["approval"]["approval_fingerprint"]
        )
        add_applied = mcp_server.reminders_apply_change(
            "update_recurrence",
            handle=reminder_handle,
            expected_title="Synthetic runtime reminder",
            expected_recurrence_present="false",
            recurrence_frequency="weekly",
            recurrence_count=4,
            recurrence_weekdays="monday,thursday",
            approval_token=add_token,
            confirm_apply=True,
        )

        mcp_server.apply_reminder_change = lambda operation, **kwargs: apply_change(
            operation, weekly, **kwargs
        )
        replace_plan = mcp_server.reminders_plan_change(
            "update_recurrence",
            handle=reminder_handle,
            expected_title="Synthetic runtime reminder",
            expected_recurrence_present="true",
            expected_recurrence=weekly,
            recurrence_frequency="daily",
            recurrence_interval=2,
            recurrence_count=6,
        )
        replace_token = (
            "reminders-apply:v1:" + replace_plan["preview"]["approval"]["approval_fingerprint"]
        )
        replace_applied = mcp_server.reminders_apply_change(
            "update_recurrence",
            handle=reminder_handle,
            expected_title="Synthetic runtime reminder",
            expected_recurrence_present="true",
            expected_recurrence=weekly,
            recurrence_frequency="daily",
            recurrence_interval=2,
            recurrence_count=6,
            approval_token=replace_token,
            confirm_apply=True,
        )

        mcp_server.apply_reminder_change = lambda operation, **kwargs: apply_change(
            operation, daily, **kwargs
        )
        clear_plan = mcp_server.reminders_plan_change(
            "update_recurrence",
            handle=reminder_handle,
            expected_title="Synthetic runtime reminder",
            expected_recurrence_present="true",
            expected_recurrence=daily,
            clear_recurrence=True,
        )
        clear_token = (
            "reminders-apply:v1:" + clear_plan["preview"]["approval"]["approval_fingerprint"]
        )
        clear_applied = mcp_server.reminders_apply_change(
            "update_recurrence",
            handle=reminder_handle,
            expected_title="Synthetic runtime reminder",
            expected_recurrence_present="true",
            expected_recurrence=daily,
            clear_recurrence=True,
            approval_token=clear_token,
            confirm_apply=True,
        )
    finally:
        mcp_server.plan_reminder_change = original_plan
        mcp_server.apply_reminder_change = original_apply

    return {
        "mcp_reminders_recurrence_create_plan_status": create_plan["status"],
        "mcp_reminders_recurrence_create_apply_status": create_applied["status"],
        "mcp_reminders_recurrence_create_apply_verified": create_applied["read_back"][
            "recurrence_verified"
        ],
        "mcp_reminders_recurrence_update_add_plan_status": add_plan["status"],
        "mcp_reminders_recurrence_update_add_apply_status": add_applied["status"],
        "mcp_reminders_recurrence_update_add_apply_verified": add_applied["read_back"][
            "recurrence_verified"
        ],
        "mcp_reminders_recurrence_update_replace_plan_status": replace_plan["status"],
        "mcp_reminders_recurrence_update_replace_apply_status": replace_applied["status"],
        "mcp_reminders_recurrence_update_replace_apply_verified": replace_applied["read_back"][
            "recurrence_verified"
        ],
        "mcp_reminders_recurrence_update_clear_plan_status": clear_plan["status"],
        "mcp_reminders_recurrence_update_clear_apply_status": clear_applied["status"],
        "mcp_reminders_recurrence_update_clear_apply_verified": clear_applied["read_back"][
            "recurrence_cleared_verified"
        ],
    }


