def _messages_plan_apply_smoke(tmp_path: Path) -> dict[str, Any]:
    db_path = tmp_path / "messages-send.sqlite"
    _make_messages_db(db_path)
    search = search_message_chats("runtime", db_path=db_path)
    handle = search["results"][0]["handle"]
    body_text = "Synthetic runtime outgoing text."
    plan = plan_messages_change(
        "send-text",
        handle=handle,
        body_text=body_text,
        db_path=db_path,
    )
    token = "messages-apply:v1:" + plan["preview"]["approval"]["approval_fingerprint"]
    missing_confirmation = apply_messages_change(
        "send-text",
        handle=handle,
        body_text=body_text,
        approval_token=token,
        confirm_apply=False,
        db_path=db_path,
        script_runner=lambda _script, _timeout: "",
        read_back_timeout=0,
    )

    def runner(script: str, _timeout: float) -> str:
        if "chat id" not in script or "send messageText to targetChat" not in script:
            raise RuntimeError("Messages send smoke saw unexpected script")
        with sqlite3.connect(db_path) as connection:
            connection.execute(
                "INSERT INTO message VALUES (?, ?, ?, ?, ?, ?, ?)",
                (13, body_text, 802310700, 1, 0, "iMessage", None),
            )
            connection.execute("INSERT INTO chat_message_join VALUES (?, ?)", (1, 13))
        return ""

    result = apply_messages_change(
        "send-text",
        handle=handle,
        body_text=body_text,
        approval_token=token,
        confirm_apply=True,
        db_path=db_path,
        script_runner=runner,
        read_back_timeout=0,
    )
    read_back = result["read_back"]
    file_path = tmp_path / "runtime-outbound-packet.pdf"
    file_path.write_bytes(b"RUNTIME FILE SEND")
    file_plan = plan_messages_change(
        "send-file",
        handle=handle,
        file_path=str(file_path),
        db_path=db_path,
    )
    file_token = "messages-apply:v1:" + file_plan["preview"]["approval"]["approval_fingerprint"]

    def file_runner(script: str, _timeout: float) -> str:
        if "chat id" not in script or "send attachmentFile to targetChat" not in script:
            raise RuntimeError("Messages send-file smoke saw unexpected script")
        if str(file_path) not in script:
            raise RuntimeError("Messages send-file smoke did not receive the selected file")
        with sqlite3.connect(db_path) as connection:
            connection.execute(
                "INSERT INTO message VALUES (?, ?, ?, ?, ?, ?, ?)",
                (14, "", 802310800, 1, 0, "iMessage", None),
            )
            connection.execute("INSERT INTO chat_message_join VALUES (?, ?)", (1, 14))
            connection.execute(
                "INSERT INTO attachment VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    21,
                    "runtime-outbound-attachment-guid",
                    802310800,
                    802310800,
                    "Attachments/cc/dd/runtime-outbound-packet.pdf",
                    "com.adobe.pdf",
                    "application/pdf",
                    0,
                    1,
                    None,
                    "runtime-outbound-packet.pdf",
                    file_path.stat().st_size,
                    0,
                ),
            )
            connection.execute("INSERT INTO message_attachment_join VALUES (?, ?)", (14, 21))
        return ""

    file_result = apply_messages_change(
        "send-file",
        handle=handle,
        file_path=str(file_path),
        approval_token=file_token,
        confirm_apply=True,
        db_path=db_path,
        script_runner=file_runner,
        read_back_timeout=0,
    )
    file_read_back = file_result["read_back"]
    return {
        "messages_plan_status": plan["status"],
        "messages_plan_mode": plan["mode"],
        "messages_plan_mutation_applied": plan["mutation_applied"],
        "messages_plan_apply_available": plan["apply_available"],
        "messages_plan_idempotency_key": plan["preview"]["idempotency_key"].startswith(
            "messages-plan:v1:"
        ),
        "messages_apply_status": result["status"],
        "messages_apply_mode": result["mode"],
        "messages_apply_mutation_applied": result["mutation_applied"],
        "messages_apply_read_back_confirmed": read_back["chat_handle_confirmed"],
        "messages_apply_read_back_direction": read_back["direction"],
        "messages_apply_read_back_text_source": read_back["text_source"],
        "messages_apply_read_back_body_chars": read_back["body_chars"],
        "messages_apply_read_back_hash_ok": read_back["body_sha256"]
        == hashlib.sha256(body_text.encode("utf-8")).hexdigest(),
        "messages_apply_body_not_returned": "text" not in read_back
        and "body_text" not in read_back,
        "messages_apply_missing_confirmation": missing_confirmation["warnings"][0]["code"],
        "messages_file_plan_status": file_plan["status"],
        "messages_file_plan_operation": file_plan["preview"]["operation"],
        "messages_file_apply_status": file_result["status"],
        "messages_file_apply_mutation_applied": file_result["mutation_applied"],
        "messages_file_apply_read_back_confirmed": file_read_back["chat_handle_confirmed"],
        "messages_file_apply_attachment_filename": file_read_back["attachment_filename"],
        "messages_file_apply_attachment_content_returned": file_read_back["attachment_content_returned"],
        "messages_file_apply_file_path_returned": file_read_back["file_path_returned"],
    }


def _voice_memos_content_smoke(tmp_path: Path) -> dict[str, Any]:
    recordings_dir = tmp_path / "Recordings"
    recordings_dir.mkdir()
    db_path = recordings_dir / "CloudRecordings.db"
    _make_voice_memos_db(db_path, recordings_dir)
    search = search_voice_memos("runtime", db_path=db_path, recordings_dir=recordings_dir)
    handle = search["results"][0]["handle"]
    content = get_voice_memo_recording(
        handle,
        db_path=db_path,
        recordings_dir=recordings_dir,
        max_chars=4000,
    )
    export = export_voice_memo_audio(
        handle,
        output_dir=tmp_path / "voice-memo-exports",
        filename="runtime-memo",
        db_path=db_path,
        recordings_dir=recordings_dir,
    )
    legacy_content = get_voice_memo_recording("voice_memos:recording:1", db_path=db_path)
    legacy_export = export_voice_memo_audio(
        "voice_memos:recording:1",
        output_dir=tmp_path / "voice-memo-exports",
        db_path=db_path,
    )
    return {
        "voice_memos_opaque_handle": handle.startswith("voice_memos:recording:v1:"),
        "voice_memos_content_status": content["status"],
        "voice_memos_transcript_status": content["result"]["transcript_status"],
        "voice_memos_transcript_chars": content["result"]["transcript_chars"],
        "voice_memos_audio_content_returned": content["result"]["audio_content_returned"],
        "voice_memos_export_status": export["status"],
        "voice_memos_audio_content_exported": export["result"]["audio_content_exported"],
        "voice_memos_export_privacy_exported": export["privacy"]["content_exported"],
        "voice_memos_exported_bytes": export["result"]["exported_bytes"],
        "voice_memos_legacy_content_status": legacy_content["status"],
        "voice_memos_legacy_content_warning": legacy_content["warnings"][0]["code"],
        "voice_memos_legacy_export_status": legacy_export["status"],
        "voice_memos_legacy_export_warning": legacy_export["warnings"][0]["code"],
        "voice_memos_legacy_export_privacy_exported": legacy_export["privacy"][
            "content_exported"
        ],
    }


def _icloud_drive_content_smoke(tmp_path: Path) -> dict[str, Any]:
    root = tmp_path / "CloudDocs"
    _make_icloud_drive_root(root)
    search = search_icloud_drive_metadata("synthetic-runtime-file", root=root)
    handle = search["results"][0]["handle"]
    content = get_icloud_drive_content(handle, root=root, max_chars=4000)
    root_metadata = get_icloud_drive_root_metadata(root=root)
    root_list = list_icloud_drive_folder(root_metadata["result"]["handle"], root=root, limit=3)
    folder_search = search_icloud_drive_metadata("Runtime Packets", root=root)
    list_folder = list_icloud_drive_folder(
        folder_search["results"][0]["handle"],
        root=root,
        limit=2,
    )
    list_tree = list_icloud_drive_folder_tree(
        folder_search["results"][0]["handle"],
        root=root,
        depth=2,
        limit=8,
    )
    legacy_content = get_icloud_drive_content("icloud:file:synthetic-runtime-file.md", root=root)
    export_search = search_icloud_drive_metadata("runtime-export-packet", root=root)
    export = export_icloud_drive_file(
        export_search["results"][0]["handle"],
        root=root,
        output_dir=tmp_path / "exports",
        filename="../runtime export.bin",
    )
    return {
        "icloud_opaque_handle": handle.startswith("icloud:file:v1:"),
        "icloud_content_status": content["status"],
        "icloud_content_chars": content["result"]["content_chars"],
        "icloud_content_sha256_present": bool(content["result"]["content_sha256"]),
        "icloud_root_status": root_metadata["status"],
        "icloud_root_handle_opaque": root_metadata["result"]["handle"].startswith("icloud:file:v1:"),
        "icloud_root_is_root": root_metadata["result"]["is_root"],
        "icloud_root_raw_path_returned": str(root) in json.dumps(root_metadata),
        "icloud_root_list_status": root_list["status"],
        "icloud_root_list_result_count": root_list["result_count"],
        "icloud_list_folder_status": list_folder["status"],
        "icloud_list_folder_result_count": list_folder["result_count"],
        "icloud_list_folder_recursive": list_folder["query"]["recursive"],
        "icloud_list_folder_content_returned": "content_text" in json.dumps(list_folder),
        "icloud_list_folder_raw_path_returned": str(root) in json.dumps(list_folder),
        "icloud_list_tree_status": list_tree["status"],
        "icloud_list_tree_result_count": list_tree["result_count"],
        "icloud_list_tree_recursive": list_tree["query"]["recursive"],
        "icloud_list_tree_content_returned": "content_text" in json.dumps(list_tree),
        "icloud_list_tree_raw_path_returned": str(root) in json.dumps(list_tree),
        "icloud_export_status": export["status"],
        "icloud_export_content_returned": export["result"]["file_content_returned"],
        "icloud_export_content_exported": export["result"]["file_content_exported"],
        "icloud_export_source_path_returned": export["result"]["source_path_returned"],
        "icloud_exported_bytes": export["result"]["exported_bytes"],
        "icloud_legacy_content_status": legacy_content["status"],
        "icloud_legacy_content_warning": legacy_content["warnings"][0]["code"],
    }


