    def replacing_mcp_identity_race_resolve(*args: Any, **kwargs: Any) -> Any:
        nonlocal mcp_identity_race_resolve_calls, mcp_identity_race_replaced
        resolved = original_resolve_handle(*args, **kwargs)
        mcp_identity_race_resolve_calls += 1
        if (
            not mcp_identity_race_replaced
            and mcp_identity_race_resolve_calls >= 2
            and isinstance(resolved, Path)
        ):
            mcp_identity_race_replaced = True
            mcp_identity_race_target.unlink()
            mcp_identity_race_target.write_text(mcp_identity_race_text, encoding="utf-8")
        return resolved

