    def _calendar_future_series_event_url_runner_for(
        payload: dict[str, Any],
        timeout: float,
        *,
        current_event_url: str,
    ) -> dict[str, Any]:
        current_recurrence = {
            "frequency": "weekly",
            "interval": 1,
            "count": 6,
            "recurrence_present": True,
        }
        event_url = "https://meet.example.invalid/future-series-url"
        event_url_sha256 = hashlib.sha256(event_url.encode("utf-8")).hexdigest()
        current_event_url_present = bool(current_event_url)
        current_event_url_sha256 = (
            hashlib.sha256(current_event_url.encode("utf-8")).hexdigest()
            if current_event_url_present
            else ""
        )
        if payload["command"] != "calendar_apply_change":
            result = _calendar_recurrence_future_delete_runner(payload, timeout)
            if "events" in result:
                for event in result["events"]:
                    event["recurrence_present"] = True
                    event["recurrence"] = current_recurrence
                    event["url_present"] = current_event_url_present
                    if current_event_url_present:
                        event["event_url_safe_sha256"] = current_event_url_sha256
                    else:
                        event.pop("event_url_safe_sha256", None)
            if "event" in result:
                result["event"]["recurrence_present"] = True
                result["event"]["recurrence"] = current_recurrence
                result["event"]["url_present"] = current_event_url_present
                if current_event_url_present:
                    result["event"]["event_url_safe_sha256"] = current_event_url_sha256
                else:
                    result["event"].pop("event_url_safe_sha256", None)
            return result
        if payload["operation"] == "update":
            clear_requested = payload.get("event_url_clear_requested") is True
            if payload.get("future_series_event_url_update_requested") is not True:
                raise AssertionError("future-series event URL did not bind URL flag")
            if payload.get("future_series_scalar_update_requested") is not False:
                raise AssertionError("future-series event URL incorrectly bound scalar flag")
            if payload.get("future_series_reschedule_requested") is not False:
                raise AssertionError("future-series event URL incorrectly bound reschedule flag")
            if payload.get("future_series_availability_update_requested") is not False:
                raise AssertionError("future-series event URL incorrectly bound availability flag")
            if payload.get("recurrence_update_scope") != "future_events":
                raise AssertionError("future-series event URL did not bind future_events scope")
            if "recurrence" in payload:
                raise AssertionError("future-series event URL unexpectedly carried recurrence fields")
            if payload.get("expected_recurrence_present") is not True:
                raise AssertionError("future-series event URL did not bind expected recurrence")
            if payload.get("expected_recurrence") != current_recurrence:
                raise AssertionError("future-series event URL did not bind expected recurrence shape")
            if clear_requested:
                if current_event_url_present is not True:
                    raise AssertionError("future-series event URL clear runner missing current URL")
                if payload.get("expected_event_url_present") is not True:
                    raise AssertionError("future-series event URL clear did not bind expected URL presence")
                if payload.get("expected_event_url_sha256") != current_event_url_sha256:
                    raise AssertionError("future-series event URL clear did not bind expected URL hash")
                if payload.get("event_url") not in {"", None}:
                    raise AssertionError("future-series event URL clear unexpectedly carried proposed URL")
            else:
                if payload.get("expected_event_url_present") is not current_event_url_present:
                    raise AssertionError("future-series event URL did not bind expected URL presence")
                if (
                    current_event_url_present
                    and payload.get("expected_event_url_sha256")
                    != current_event_url_sha256
                ):
                    raise AssertionError("future-series event URL did not bind expected URL hash")
                if payload.get("event_url") != event_url:
                    raise AssertionError("future-series event URL did not bind proposed URL")
            expected_fields = {
                "occurrence_start_date": "2026-06-03T17:00:00.000Z",
                "occurrence_end_date": "2026-06-03T18:00:00.000Z",
                "previous_occurrence_start_date": "2026-05-27T17:00:00.000Z",
                "previous_occurrence_end_date": "2026-05-27T18:00:00.000Z",
                "future_occurrence_start_date": "2026-06-10T17:00:00.000Z",
                "future_occurrence_end_date": "2026-06-10T18:00:00.000Z",
            }
            for field, expected in expected_fields.items():
                if payload.get(field) != expected:
                    raise AssertionError(f"future-series event URL did not bind {field}")
            result = _calendar_runner(payload, timeout)
            result["event"]["recurrence_present"] = True
            result["event"]["recurrence"] = current_recurrence
            result["event"]["url_present"] = not clear_requested
            if clear_requested:
                result["event"].pop("event_url_safe_sha256", None)
            else:
                result["event"]["event_url_safe_sha256"] = event_url_sha256
            result["read_back"] = {
                "future_series_event_url_updated_verified": True,
                "selected_occurrence_updated_verified": True,
                "future_occurrence_updated_verified": True,
                "previous_occurrence_verified_present": True,
                "event_url_present": not clear_requested,
            }
            if not clear_requested:
                result["read_back"]["event_url_safe_sha256"] = event_url_sha256
            return result
        return _calendar_runner(payload, timeout)

