    def _contains_raw_alarm_email_key(value: Any) -> bool:
        if isinstance(value, dict):
            return any(
                key == "alarm_email_address" or _contains_raw_alarm_email_key(item)
                for key, item in value.items()
            )
        if isinstance(value, list):
            return any(_contains_raw_alarm_email_key(item) for item in value)
        return False

