    def _calendar_recurrence_update_runner(
        payload: dict[str, Any],
        timeout: float,
    ) -> dict[str, Any]:
        recurrence = {
            "frequency": "weekly",
            "interval": 1,
            "count": 6,
            "recurrence_present": True,
        }
        if payload["command"] != "calendar_apply_change":
            result = _calendar_recurrence_delete_runner(payload, timeout)
            if "events" in result:
                for event in result["events"]:
                    event["recurrence_present"] = True
                    event["recurrence"] = recurrence
            if "event" in result:
                result["event"]["recurrence_present"] = True
                result["event"]["recurrence"] = recurrence
            return result
        if payload["command"] == "calendar_apply_change" and payload["operation"] == "update":
            if payload.get("recurrence_update_scope") != "this_event":
                raise AssertionError("recurring occurrence update did not bind this_event scope")
            if payload.get("expected_recurrence_present") is not True:
                raise AssertionError("recurring occurrence update did not bind expected recurrence")
            if payload.get("expected_recurrence") != recurrence:
                raise AssertionError("recurring occurrence update did not bind expected recurrence shape")
            expected_fields = {
                "occurrence_start_date": "2026-06-03T17:00:00.000Z",
                "occurrence_end_date": "2026-06-03T18:00:00.000Z",
                "adjacent_occurrence_start_date": "2026-06-10T17:00:00.000Z",
                "adjacent_occurrence_end_date": "2026-06-10T18:00:00.000Z",
            }
            for field, expected in expected_fields.items():
                if payload.get(field) != expected:
                    raise AssertionError(f"recurring occurrence update did not bind {field}")
            if payload.get("availability") is not None and payload.get("expected_availability") != 0:
                raise AssertionError("recurring occurrence availability update did not bind expected availability")
            if payload.get("event_url_requested") and payload.get("expected_event_url_present") not in {
                False,
                True,
            }:
                raise AssertionError("recurring occurrence event URL update did not bind expected URL state")
            if (
                payload.get("event_url_requested")
                and payload.get("expected_event_url_present") is True
                and payload.get("expected_event_url_sha256")
                != recurrence_update_event_url_replace_current_sha256
            ):
                return {
                    "schema_version": 1,
                    "status": "error",
                    "source": "calendar",
                    "authorization_status": "authorized",
                    "warnings": [
                        {
                            "code": "expected_state_mismatch",
                            "message": "Calendar event URL did not match expected state.",
                        }
                    ],
                }
            if payload.get("event_url_clear_requested") and (
                payload.get("expected_event_url_present") is not True
                or not payload.get("expected_event_url_sha256")
            ):
                raise AssertionError("recurring occurrence event URL clear did not bind expected URL proof")
            if payload.get("structured_location"):
                if payload.get("expected_structured_location"):
                    if payload.get("expected_structured_location_present") is not True:
                        raise AssertionError("recurring occurrence structured location replacement did not bind expected presence")
                elif payload.get("expected_structured_location_present") is not False:
                    raise AssertionError("recurring occurrence structured location add did not bind expected absence")
            if payload.get("structured_location_clear_requested"):
                if payload.get("expected_structured_location_present") is not True or not payload.get(
                    "expected_structured_location"
                ):
                    raise AssertionError("recurring occurrence structured location clear did not bind expected state")
            if payload.get("adjacent_occurrence_event_url_present") is not False:
                raise AssertionError("recurring occurrence update did not bind adjacent URL absence")
            if payload.get("adjacent_occurrence_event_url_sha256") != "":
                raise AssertionError("recurring occurrence update did not bind adjacent URL hash")
            if payload.get("adjacent_occurrence_location_present") is not True:
                raise AssertionError("recurring occurrence update did not bind adjacent location presence")
            if not payload.get("adjacent_occurrence_location_sha256"):
                raise AssertionError("recurring occurrence update did not bind adjacent location hash")
            if payload.get("adjacent_occurrence_structured_location_present") is not False:
                raise AssertionError("recurring occurrence update did not bind adjacent structured-location absence")
            if payload.get("adjacent_occurrence_structured_location_sha256") != "":
                raise AssertionError("recurring occurrence update did not bind adjacent structured-location hash")
            if payload.get("adjacent_occurrence_alarm_state_present") is not False:
                raise AssertionError("recurring occurrence update did not bind adjacent alarm-state absence")
            if payload.get("adjacent_occurrence_alarm_state_sha256") != "":
                raise AssertionError("recurring occurrence update did not bind adjacent alarm-state hash")
            result = _calendar_runner(payload, timeout)
            result["event"]["recurrence_present"] = True
            result["event"]["recurrence"] = recurrence
            selected_calendar_move = bool(payload.get("target_calendar_id"))
            rescheduled = (
                not _same_instant(payload["start_date"], payload["occurrence_start_date"])
                or not _same_instant(payload["end_date"], payload["occurrence_end_date"])
            )
            result["read_back"] = {
                "selected_occurrence_updated_verified": True,
                "adjacent_occurrence_verified_present": True,
                "adjacent_occurrence_event_url_verified": True,
                "adjacent_occurrence_location_verified": True,
                "adjacent_occurrence_alarm_verified": True,
                "selected_occurrence_rescheduled_verified": rescheduled,
                "original_occurrence_verified_absent": rescheduled,
                "selected_occurrence_calendar_move_verified": selected_calendar_move,
                "adjacent_occurrence_calendar_verified": True,
                "all_day_verified": bool(payload.get("all_day"))
                != bool(payload.get("expected_all_day")),
                "structured_location_verified": bool(payload.get("structured_location")),
                "structured_location_cleared_verified": bool(
                    payload.get("structured_location_clear_requested")
                ),
                "display_alarm_verified": (
                    bool(payload.get("selected_occurrence_alarm_update_requested"))
                    and (
                    payload.get("alarm_offsets_minutes", [])
                    != payload.get("expected_alarm_offsets_minutes", [])
                    or payload.get("alarm_absolute_dates", [])
                    != payload.get("expected_alarm_absolute_dates", [])
                    )
                ),
                "action_alarm_verified": bool(
                    payload.get("selected_occurrence_alarm_update_requested")
                )
                and _calendar_alarm_action_changed(payload),
            }
            return result
        return _calendar_runner(payload, timeout)

