def _contacts_content_smoke() -> dict[str, Any]:
    search = search_contacts("runtime", contacts_runner=_contacts_runner)
    handle = search["results"][0]["handle"]
    content = get_contact(handle, contacts_runner=_contacts_runner)
    legacy_content = get_contact("contacts:contact:runtime-contact-1")
    return {
        "contacts_opaque_handle": handle.startswith("contacts:contact:v1:"),
        "contacts_content_status": content["status"],
        "contacts_email_count": len(content["result"]["email_addresses"]),
        "contacts_note_status": content["result"]["note_status"],
        "contacts_note_chars": content["result"]["note_chars"],
        "contacts_note_safe_sha_present": bool(content["result"]["note_safe_sha256"]),
        "contacts_legacy_content_status": legacy_content["status"],
        "contacts_legacy_content_warning": legacy_content["warnings"][0]["code"],
    }


def _contacts_backup_smoke(tmp_path: Path) -> dict[str, Any]:
    count = count_contacts(max_contacts=123, contacts_runner=_contacts_runner)
    archive = export_contacts_archive(
        output_dir=tmp_path / "contacts-runtime-backup",
        filename_prefix="runtime-contacts",
        max_contacts=123,
        contacts_runner=_contacts_runner,
    )
    archive_result = archive["result"]
    return {
        "contacts_count_status": count["status"],
        "contacts_count_live_count": count["result"]["live_count"],
        "contacts_count_complete": count["result"]["count_complete"],
        "contacts_export_status": archive["status"],
        "contacts_export_archive_verified": archive_result["archive_verified"],
        "contacts_export_counts_match": archive_result["counts_match"],
        "contacts_export_live_count": archive_result["live_count"],
        "contacts_export_json_contact_count": archive_result["json_contact_count"],
        "contacts_export_vcard_contact_count": archive_result["vcard_contact_count"],
        "contacts_export_json_exists": Path(archive_result["json_path"]).exists(),
        "contacts_export_vcard_exists": Path(archive_result["vcard_path"]).exists(),
        "contacts_export_manifest_exists": Path(archive_result["manifest_path"]).exists(),
        "contacts_export_contact_data_returned": archive_result["contact_data_returned"],
        "contacts_export_contact_data_exported": archive_result["contact_data_exported"],
        "contacts_export_notes_exported": archive_result["notes_exported"],
    }


def _contacts_label_smoke() -> dict[str, Any]:
    # v1.180A: free-form custom labels round-trip verbatim (no lowercasing /
    # space->underscore normalization) up to 255 chars; control chars are rejected.
    freeform = "My Custom Label (2nd)!"
    plan = plan_contact_change(
        "create",
        contact_type="person",
        given_name="Synthetic",
        family_name="Runtime Label",
        email_addresses=[{"label": freeform, "value": "synthetic-label@example.invalid"}],
        contacts_runner=_contacts_runner,
    )
    token = "contacts-apply:v1:" + plan["preview"]["approval"]["approval_fingerprint"]
    applied = apply_contact_change(
        "create",
        contact_type="person",
        given_name="Synthetic",
        family_name="Runtime Label",
        email_addresses=[{"label": freeform, "value": "synthetic-label@example.invalid"}],
        approval_token=token,
        confirm_apply=True,
        contacts_runner=_contacts_runner,
    )
    boundary = "L" + "a" * 253 + "z"  # exactly 255 chars
    boundary_plan = plan_contact_change(
        "create",
        contact_type="person",
        given_name="Synthetic",
        family_name="Runtime Boundary",
        phone_numbers=[{"label": boundary, "value": "+1 555 0100"}],
        contacts_runner=_contacts_runner,
    )
    oversize_plan = plan_contact_change(
        "create",
        contact_type="person",
        given_name="Synthetic",
        family_name="Runtime Oversize",
        email_addresses=[{"label": "x" * 256, "value": "synthetic-oversize@example.invalid"}],
        contacts_runner=_contacts_runner,
    )
    control_plan = plan_contact_change(
        "create",
        contact_type="person",
        given_name="Synthetic",
        family_name="Runtime Control",
        email_addresses=[{"label": "Line\nBreak", "value": "synthetic-control@example.invalid"}],
        contacts_runner=_contacts_runner,
    )
    # Distinct-label proof: two labels differing only in case/spacing are preserved as
    # two distinct verbatim strings by the plan, matching the Swift helper's verbatim
    # `labelsMatchVerbatim` create-idempotency comparison (v1.180A consistency).
    cased_plan = plan_contact_change(
        "create",
        contact_type="person",
        given_name="Synthetic",
        family_name="Runtime Cased",
        phone_numbers=[
            {"label": "Work Phone", "value": "+1 555 0101"},
            {"label": "work_phone", "value": "+1 555 0102"},
        ],
        contacts_runner=_contacts_runner,
    )
    cased_labels = [entry["label"] for entry in cased_plan["preview"]["proposed"]["phone_numbers"]]
    return {
        "contacts_freeform_label_plan_status": plan["status"],
        "contacts_freeform_label_preserved": (
            plan["preview"]["proposed"]["email_addresses"][0]["label"] == freeform
        ),
        "contacts_freeform_label_apply_status": applied["status"],
        "contacts_freeform_label_apply_verified": applied["status"] == "ok",
        "contacts_freeform_label_255_allowed": (
            boundary_plan["status"] == "ok"
            and boundary_plan["preview"]["proposed"]["phone_numbers"][0]["label"] == boundary
        ),
        "contacts_freeform_label_oversize_refused": (
            oversize_plan["status"] == "error"
            and any(w["code"] == "label_too_large" for w in oversize_plan["warnings"])
        ),
        "contacts_freeform_label_control_refused": (
            control_plan["status"] == "error"
            and any(w["code"] == "invalid_label" for w in control_plan["warnings"])
        ),
        "contacts_freeform_label_case_space_distinct": (
            cased_plan["status"] == "ok"
            and cased_labels == ["Work Phone", "work_phone"]
        ),
    }


