def _photos_content_smoke(tmp_path: Path) -> dict[str, Any]:
    search = search_photos("runtime", photos_runner=_photos_runner)
    handle = search["results"][0]["handle"]
    detail = get_photo_asset(handle, photos_runner=_photos_runner)
    album_search = search_photo_albums("runtime", photos_runner=_photos_runner)
    album_handle = album_search["results"][0]["handle"]
    album_detail = get_photo_album(album_handle, photos_runner=_photos_runner)
    album_assets = list_photo_album_assets(album_handle, photos_runner=_photos_runner)
    export = export_photo_asset(
        handle,
        output_dir=tmp_path / "photo-exports",
        filename="runtime-photo.jpg",
        photos_runner=_photos_runner,
    )
    legacy_detail = get_photo_asset("photos:asset:runtime-photo-1")
    legacy_export = export_photo_asset(
        "photos:asset:runtime-photo-1",
        output_dir=tmp_path / "photo-exports",
    )
    return {
        "photos_opaque_handle": handle.startswith("photos:asset:v1:"),
        "photos_detail_status": detail["status"],
        "photos_resource_count": len(detail["result"]["resources"]),
        "photos_asset_content_returned": detail["result"]["asset_content_returned"],
        "photos_album_search_status": album_search["status"],
        "photos_album_opaque_handle": album_handle.startswith("photos:album:v1:"),
        "photos_album_detail_status": album_detail["status"],
        "photos_album_raw_id_returned": "runtime-album-1" in str(album_detail),
        "photos_album_assets_status": album_assets["status"],
        "photos_album_assets_count": album_assets["result_count"],
        "photos_album_assets_parent_handle": album_assets["parent"]["handle"].startswith(
            "photos:album:v1:"
        ),
        "photos_album_assets_asset_handle": album_assets["results"][0]["handle"].startswith(
            "photos:asset:v1:"
        ),
        "photos_album_assets_content_returned": album_assets["results"][0][
            "asset_content_returned"
        ],
        "photos_album_assets_raw_ids_returned": (
            "runtime-photo-1" in str(album_assets)
            or "runtime-album-1" in str(album_assets)
        ),
        "photos_export_status": export["status"],
        "photos_asset_content_exported": export["result"]["asset_content_exported"],
        "photos_export_privacy_exported": export["privacy"]["content_exported"],
        "photos_exported_bytes": export["result"]["exported_bytes"],
        "photos_legacy_detail_status": legacy_detail["status"],
        "photos_legacy_detail_warning": legacy_detail["warnings"][0]["code"],
        "photos_legacy_export_status": legacy_export["status"],
        "photos_legacy_export_warning": legacy_export["warnings"][0]["code"],
        "photos_legacy_export_privacy_exported": legacy_export["privacy"][
            "content_exported"
        ],
    }


def _photos_plan_apply_smoke(tmp_path: Path) -> dict[str, Any]:
    source = tmp_path / "IMG_RUNTIME_IMPORT.JPG"
    source.write_bytes(b"synthetic runtime photo bytes")
    plan = plan_photo_change("import", source_file=source)
    token = "photos-apply:v1:" + plan["preview"]["approval"]["approval_fingerprint"]
    result = apply_photo_change(
        "import",
        source_file=source,
        approval_token=token,
        confirm_apply=True,
        photos_runner=_photos_runner,
    )
    missing_confirmation = apply_photo_change(
        "import",
        source_file=source,
        approval_token=token,
        photos_runner=_photos_runner,
    )
    return {
        "photos_plan_status": plan["status"],
        "photos_plan_mode": plan["mode"],
        "photos_plan_mutation_applied": plan["mutation_applied"],
        "photos_plan_apply_available": plan["apply_available"],
        "photos_plan_idempotency_key": plan["preview"]["idempotency_key"].startswith(
            "photos-plan:v1:"
        ),
        "photos_apply_status": result["status"],
        "photos_apply_mode": result["mode"],
        "photos_apply_mutation_applied": result["mutation_applied"],
        "photos_apply_read_back_filename": result["read_back"]["primary_filename"],
        "photos_apply_missing_confirmation": missing_confirmation["warnings"][0]["code"],
    }


def _photos_update_flags_smoke() -> dict[str, Any]:
    search = search_photos("runtime", photos_runner=_photos_runner)
    handle = search["results"][0]["handle"]
    plan = plan_photo_change(
        "update_flags",
        handle=handle,
        favorite=True,
        expected_favorite=False,
        expected_hidden=False,
        photos_runner=_photos_runner,
    )
    token = "photos-apply:v1:" + plan["preview"]["approval"]["approval_fingerprint"]
    result = apply_photo_change(
        "update_flags",
        handle=handle,
        favorite=True,
        expected_favorite=False,
        expected_hidden=False,
        approval_token=token,
        confirm_apply=True,
        photos_runner=_photos_runner,
    )
    stale = plan_photo_change(
        "update_flags",
        handle=handle,
        favorite=True,
        expected_favorite=True,
        expected_hidden=False,
        photos_runner=_photos_runner,
    )
    return {
        "photos_update_flags_plan_status": plan["status"],
        "photos_update_flags_plan_operation": plan["preview"]["operation"],
        "photos_update_flags_plan_target_handle": plan["preview"]["target"]["handle"].startswith(
            "photos:asset:v1:"
        ),
        "photos_update_flags_apply_status": result["status"],
        "photos_update_flags_apply_mutation_applied": result["mutation_applied"],
        "photos_update_flags_apply_favorite": result["read_back"]["favorite"],
        "photos_update_flags_apply_hidden": result["read_back"]["hidden"],
        "photos_update_flags_asset_id_returned": "runtime-photo-1" in str(result),
        "photos_update_flags_stale_status": stale["status"],
        "photos_update_flags_stale_warning": stale["warnings"][0]["code"],
    }


def _photos_album_membership_smoke() -> dict[str, Any]:
    search = search_photos("runtime", photos_runner=_photos_runner)
    handle = search["results"][0]["handle"]
    album_search = search_photo_albums("runtime", photos_runner=_photos_runner)
    album_handle = album_search["results"][0]["handle"]
    plan = plan_photo_change(
        "add_to_album",
        handle=handle,
        album_handle=album_handle,
        expected_in_album=False,
        photos_runner=_photos_runner,
    )
    token = "photos-apply:v1:" + plan["preview"]["approval"]["approval_fingerprint"]
    result = apply_photo_change(
        "add_to_album",
        handle=handle,
        album_handle=album_handle,
        expected_in_album=False,
        approval_token=token,
        confirm_apply=True,
        photos_runner=_photos_runner,
    )
    def remove_runner(payload: dict[str, Any], timeout: float) -> dict[str, Any]:
        response = _photos_runner(payload, timeout)
        if payload["command"] == "photo_album_membership":
            response["in_album"] = True
        return response

    remove_plan = plan_photo_change(
        "remove_from_album",
        handle=handle,
        album_handle=album_handle,
        expected_in_album=True,
        photos_runner=remove_runner,
    )
    remove_token = "photos-apply:v1:" + remove_plan["preview"]["approval"]["approval_fingerprint"]
    remove_result = apply_photo_change(
        "remove_from_album",
        handle=handle,
        album_handle=album_handle,
        expected_in_album=True,
        approval_token=remove_token,
        confirm_apply=True,
        photos_runner=remove_runner,
    )
    return {
        "photos_album_membership_plan_status": plan["status"],
        "photos_album_membership_plan_operation": plan["preview"]["operation"],
        "photos_album_membership_plan_album_handle": plan["preview"]["target"]["album_handle"].startswith(
            "photos:album:v1:"
        ),
        "photos_album_membership_apply_status": result["status"],
        "photos_album_membership_apply_mutation_applied": result["mutation_applied"],
        "photos_album_membership_apply_in_album": result["read_back"]["in_album"],
        "photos_album_membership_remove_plan_status": remove_plan["status"],
        "photos_album_membership_remove_operation": remove_plan["preview"]["operation"],
        "photos_album_membership_remove_apply_status": remove_result["status"],
        "photos_album_membership_remove_in_album": remove_result["read_back"]["in_album"],
        "photos_album_membership_asset_id_returned": "runtime-photo-1" in str(result),
        "photos_album_membership_album_id_returned": "runtime-album-1" in str(result),
    }


def _photos_album_management_smoke() -> dict[str, Any]:
    def album_runner(payload: dict[str, Any], timeout: float) -> dict[str, Any]:
        response = _photos_runner(payload, timeout)
        if payload["command"] in {"photo_albums", "photo_album_by_id", "photo_album_assets"}:
            albums = response.get("albums")
            if isinstance(albums, list):
                for album in albums:
                    album["title"] = "Runtime Original Album"
                    album["asset_count"] = 0
                    album["estimated_asset_count"] = 0
            album = response.get("album")
            if isinstance(album, dict):
                album["title"] = "Runtime Original Album"
                album["asset_count"] = 0
                album["estimated_asset_count"] = 0
        return response

    create_plan = plan_photo_change(
        "create_album",
        album_title="Runtime Created Album",
        photos_runner=album_runner,
    )
    create_token = "photos-apply:v1:" + create_plan["preview"]["approval"][
        "approval_fingerprint"
    ]
    create_result = apply_photo_change(
        "create_album",
        album_title="Runtime Created Album",
        approval_token=create_token,
        confirm_apply=True,
        photos_runner=album_runner,
    )
    album_search = search_photo_albums("Runtime", photos_runner=album_runner)
    album_handle = album_search["results"][0]["handle"]
    rename_plan = plan_photo_change(
        "rename_album",
        album_handle=album_handle,
        new_album_title="Runtime Renamed Album",
        photos_runner=album_runner,
    )
    rename_token = "photos-apply:v1:" + rename_plan["preview"]["approval"][
        "approval_fingerprint"
    ]
    rename_result = apply_photo_change(
        "rename_album",
        album_handle=album_handle,
        new_album_title="Runtime Renamed Album",
        approval_token=rename_token,
        confirm_apply=True,
        photos_runner=album_runner,
    )
    delete_plan = plan_photo_change(
        "delete_album",
        album_handle=album_handle,
        photos_runner=album_runner,
    )
    delete_token = "photos-apply:v1:" + delete_plan["preview"]["approval"][
        "approval_fingerprint"
    ]
    delete_result = apply_photo_change(
        "delete_album",
        album_handle=album_handle,
        approval_token=delete_token,
        confirm_apply=True,
        photos_runner=album_runner,
    )
    invalid_title = plan_photo_change(
        "create_album",
        album_title="   ",
        photos_runner=album_runner,
    )
    return {
        "photos_album_create_plan_status": create_plan["status"],
        "photos_album_create_apply_status": create_result["status"],
        "photos_album_create_title": create_result["read_back"]["album"]["title"],
        "photos_album_rename_plan_status": rename_plan["status"],
        "photos_album_rename_apply_status": rename_result["status"],
        "photos_album_rename_title": rename_result["read_back"]["album"]["title"],
        "photos_album_delete_plan_status": delete_plan["status"],
        "photos_album_delete_apply_status": delete_result["status"],
        "photos_album_delete_verified_absent": delete_result["read_back"][
            "verified_absent"
        ],
        "photos_album_management_invalid_title_warning": invalid_title["warnings"][0][
            "code"
        ],
        "photos_album_management_raw_album_id_returned": (
            "runtime-album-1" in str(create_result)
            or "runtime-album-1" in str(rename_result)
            or "runtime-album-1" in str(delete_result)
            or "runtime-created-album-1" in str(create_result)
        ),
    }


def _photos_delete_smoke() -> dict[str, Any]:
    search = search_photos("runtime", photos_runner=_photos_runner)
