def _reminders_runner(payload: dict[str, Any], _timeout: float) -> dict[str, Any]:
    if payload["command"] == "reminder_lists":
        lists = [
            {
                "list_id": "runtime-list-1",
                "title": "Synthetic List",
                "allows_content_modifications": True,
                "is_subscribed": False,
                "is_immutable": False,
                "calendar_type": "local",
                "source_id": "runtime-source-1",
                "source_type": "local",
                "allowed_entity_types": ["reminder"],
                "reminder_count": 1 if payload.get("include_counts") else 0,
            },
            {
                "list_id": "runtime-list-2",
                "title": "Synthetic Target List",
                "allows_content_modifications": True,
                "is_subscribed": False,
                "is_immutable": False,
                "calendar_type": "local",
                "source_id": "runtime-source-1",
                "source_type": "local",
                "allowed_entity_types": ["reminder"],
                "reminder_count": 0,
            },
            {
                "list_id": "runtime-list-3",
                "title": "Synthetic List",
                "allows_content_modifications": True,
                "is_subscribed": False,
                "is_immutable": False,
                "calendar_type": "local",
                "source_id": "runtime-source-1",
                "source_type": "local",
                "allowed_entity_types": ["reminder"],
                "reminder_count": 0,
            },
            {
                "list_id": "runtime-list-test",
                "title": "Runtime List Old",
                "allows_content_modifications": True,
                "is_subscribed": False,
                "is_immutable": False,
                "calendar_type": "local",
                "source_id": "runtime-source-1",
                "source_type": "local",
                "allowed_entity_types": ["reminder"],
                "reminder_count": 0,
            },
            {
                "list_id": "runtime-list-busy",
                "title": "Runtime Busy List",
                "allows_content_modifications": True,
                "is_subscribed": False,
                "is_immutable": False,
                "calendar_type": "local",
                "source_id": "runtime-source-1",
                "source_type": "local",
                "allowed_entity_types": ["reminder"],
                "reminder_count": 2,
            },
        ]
        query = str(payload.get("query") or "").casefold()
        if query:
            lists = [item for item in lists if query in item["title"].casefold()]
        return {
            "schema_version": 1,
            "status": "ok",
            "source": "reminders",
            "authorization_status": "authorized",
            "lists": lists,
            "warnings": [],
        }
    if payload["command"] == "reminders":
        return {
            "schema_version": 1,
            "status": "ok",
            "source": "reminders",
            "authorization_status": "authorized",
            "reminders": [
                {
                    "reminder_id": "runtime-reminder-1",
                    "title": "Synthetic runtime reminder",
                    "list_id": "runtime-list-1",
                    "list_name": "Synthetic List",
                    "due_date": "2026-06-04T17:00:00.000Z",
                    "start_date": "",
                    "completed": False,
                    "priority": 5,
                    "notes_present": True,
                    "url_present": False,
                    "alarms_count": 1,
                }
            ],
            "warnings": [],
        }
    if payload["command"] == "reminders_for_list":
        assert payload.get("list_id") in {"runtime-list-1", "runtime-list-2"}
        reminders = [
            {
                "reminder_id": "runtime-reminder-1",
                "title": "Synthetic runtime reminder",
                "list_id": payload.get("list_id"),
                "list_name": "Synthetic List"
                if payload.get("list_id") == "runtime-list-1"
                else "Synthetic Target List",
                "due_date": "2026-06-04T17:00:00.000Z",
                "start_date": "",
                "completed": False,
                "priority": 5,
                "notes_present": True,
                "url_present": False,
                "alarms_count": 1,
            },
            {
                "reminder_id": "runtime-reminder-completed",
                "title": "Synthetic completed runtime reminder",
                "list_id": payload.get("list_id"),
                "list_name": "Synthetic List"
                if payload.get("list_id") == "runtime-list-1"
                else "Synthetic Target List",
                "due_date": "2026-06-05T17:00:00.000Z",
                "start_date": "",
                "completed": True,
                "priority": 0,
                "notes_present": False,
                "url_present": False,
                "alarms_count": 0,
            },
        ]
        if not payload.get("include_completed"):
            reminders = [item for item in reminders if not item["completed"]]
        return {
            "schema_version": 1,
            "status": "ok",
            "source": "reminders",
            "authorization_status": "authorized",
            "list": {
                "list_id": payload.get("list_id"),
                "title": "Synthetic List"
                if payload.get("list_id") == "runtime-list-1"
                else "Synthetic Target List",
                "allows_content_modifications": True,
                "is_subscribed": False,
                "is_immutable": False,
                "calendar_type": "local",
                "source_id": "runtime-source-1",
                "source_type": "local",
                "allowed_entity_types": ["reminder"],
                "reminder_count": len(reminders),
            },
            "reminders": reminders[: payload.get("limit", 20)],
            "warnings": [],
        }
    if payload["command"] == "reminder_by_id":
        reminder = {
            "reminder_id": "runtime-reminder-1",
            "title": "Synthetic runtime reminder",
            "list_id": "runtime-list-1",
            "list_name": "Synthetic List",
            "due_date": "2026-06-04T17:00:00.000Z",
            "start_date": "",
            "completed": False,
            "priority": 5,
            "notes_present": True,
            "url_present": False,
            "alarms_count": 1,
        }
        if payload.get("include_content", True):
            reminder["notes"] = "Synthetic reminder notes."
        return {
            "schema_version": 1,
            "status": "ok",
            "source": "reminders",
            "reminder": reminder,
            "warnings": [],
        }
    if payload["command"] == "reminder_apply_change":
        if payload.get("operation") == "move_to_list":
            if payload.get("expected_list_id") != "runtime-list-1":
                return {
                    "schema_version": 1,
                    "status": "error",
                    "source": "reminders",
                    "authorization_status": "authorized",
                    "warnings": [
                        {
                            "code": "expected_state_mismatch",
                            "message": "Reminder list did not match expected state.",
                        }
                    ],
                }
            assert payload.get("target_list_id") == "runtime-list-2"
            assert payload.get("target_list_title") == "Synthetic Target List"
        if payload.get("operation") == "update_url":
            assert payload.get("url")
            assert payload.get("expected_url_present") is False
            assert payload.get("expected_url_sha256") == ""
        if payload.get("operation") == "delete":
            return {
                "schema_version": 1,
                "status": "ok",
                "source": "reminders",
                "authorization_status": "authorized",
                "deleted": True,
                "read_back": {
                    "deleted": True,
                    "verified_absent": True,
                },
                "warnings": [],
            }
        reminder_payload = {
            "reminder_id": payload.get("reminder_id", "runtime-created-reminder-1"),
            "title": payload.get("title") or payload.get("expected_title"),
            "list_id": "runtime-list-2"
            if payload.get("operation") == "move_to_list"
            else "runtime-list-1",
            "list_name": "Synthetic Target List"
            if payload.get("operation") == "move_to_list"
            else payload.get("list_name") or "Synthetic List",
            "due_date": payload.get("due_date") or "2026-06-04T17:00:00.000Z",
            "start_date": payload.get("start_date") or "",
            "completed": payload.get("operation") == "complete",
            "priority": payload.get("priority", 5),
            "notes_present": bool(payload.get("notes")),
            "url_present": payload.get("operation") == "update_url",
            "url_safe_sha256": hashlib.sha256(str(payload.get("url") or "").encode("utf-8")).hexdigest()
            if payload.get("operation") == "update_url"
            else "",
            "alarms_count": 0,
        }
        if payload.get("operation") in {
            "create_with_recurrence",
            "update_recurrence",
        }:
            recurrence = payload.get("recurrence")
            recurring = (
                isinstance(recurrence, dict)
                and recurrence.get("recurrence_present") is True
                and not payload.get("clear_recurrence")
            )
            reminder_payload["recurrence_present"] = recurring
            reminder_payload["recurrence"] = (
                recurrence
                if recurring
                else {"frequency": "", "interval": 0, "count": 0, "recurrence_present": False}
            )
        return {
            "schema_version": 1,
            "status": "ok",
            "source": "reminders",
            "authorization_status": "authorized",
            "reminder": reminder_payload,
            "target_list_verified": payload.get("operation") == "move_to_list",
            "warnings": [],
        }
    if payload["command"] == "reminder_list_apply_change":
        operation = payload.get("operation")
        if operation == "create_list":
            assert payload.get("source_list_id") == "runtime-list-1"
            assert payload.get("list_title") == "Runtime List New"
            return {
                "schema_version": 1,
                "status": "ok",
                "source": "reminders",
                "authorization_status": "authorized",
                "mutation_applied": True,
                "list": {
                    "list_id": "runtime-list-created",
                    "title": "Runtime List New",
                    "allows_content_modifications": True,
                    "is_subscribed": False,
                    "is_immutable": False,
                    "calendar_type": "local",
                    "source_id": "runtime-source-1",
                    "source_type": "local",
                    "allowed_entity_types": ["reminder"],
                    "reminder_count": 0,
                },
                "read_back": {
                    "source_list_verified": True,
                    "list_empty_verified": True,
                },
                "warnings": [],
            }
        if operation == "rename_list":
            assert payload.get("list_id") == "runtime-list-test"
            assert payload.get("expected_list_title") == "Runtime List Old"
            assert payload.get("new_list_title") == "Runtime List New"
            return {
                "schema_version": 1,
                "status": "ok",
                "source": "reminders",
                "authorization_status": "authorized",
                "mutation_applied": True,
                "list": {
                    "list_id": "runtime-list-test",
                    "title": "Runtime List New",
                    "allows_content_modifications": True,
                    "is_subscribed": False,
                    "is_immutable": False,
                    "calendar_type": "local",
                    "source_id": "runtime-source-1",
                    "source_type": "local",
                    "allowed_entity_types": ["reminder"],
                    "reminder_count": 0,
                },
                "read_back": {
                    "list_renamed_verified": True,
                    "list_empty_verified": True,
                },
                "warnings": [],
            }
        if operation == "delete_list":
            assert payload.get("list_id") == "runtime-list-test"
            assert payload.get("expected_list_title") == "Runtime List Old"
            return {
                "schema_version": 1,
                "status": "ok",
                "source": "reminders",
                "authorization_status": "authorized",
                "mutation_applied": True,
                "list": None,
                "read_back": {
                    "list_deleted_verified": True,
                    "list_absent_verified": True,
                    "list_empty_verified": True,
                },
                "warnings": [],
            }
        if operation == "delete_list_with_migration":
            assert payload.get("list_id") == "runtime-list-busy"
            assert payload.get("target_list_id") == "runtime-list-2"
            assert payload.get("expected_list_title") == "Runtime Busy List"
            assert payload.get("expected_target_list_title") == "Synthetic Target List"
            assert payload.get("expected_migration_count") == 2
            assert payload.get("expected_target_count") == 0
            assert payload.get("migrate_before_delete") is True
            return {
                "schema_version": 1,
                "status": "ok",
                "source": "reminders",
                "authorization_status": "authorized",
                "mutation_applied": True,
                "list": None,
                "read_back": {
                    "list_migrated_verified": True,
                    "migrated_count": 2,
                    "target_count_before": 0,
                    "target_count_after": 2,
                    "source_list_empty_verified": True,
                    "target_list_verified": True,
                    "list_deleted_verified": True,
                    "list_absent_verified": True,
                },
                "warnings": [],
            }
        raise RuntimeError("unexpected reminders list operation")
    raise RuntimeError("unexpected reminders helper command")


