def _reminders_apply_smoke() -> dict[str, Any]:
    search = search_reminders_eventkit("runtime", eventkit_runner=_reminders_runner)
    handle = search["results"][0]["handle"]
    current_list_handle = search["results"][0]["list_handle"]
    list_search = search_reminder_lists("Target", eventkit_runner=_reminders_runner)
    target_list_handle = list_search["results"][0]["handle"]
    list_items = list_reminder_items(
        target_list_handle,
        limit=1,
        eventkit_runner=_reminders_runner,
    )
    list_items_with_completed = list_reminder_items(
        current_list_handle,
        include_completed=True,
        eventkit_runner=_reminders_runner,
    )
    plan = plan_reminder_change(
        "complete",
        handle=handle,
        expected_title="Synthetic runtime reminder",
        expected_completed=False,
    )
    token = "reminders-apply:v1:" + plan["preview"]["approval"]["approval_fingerprint"]
    result = apply_reminder_change(
        "complete",
        handle=handle,
        expected_title="Synthetic runtime reminder",
        expected_completed=False,
        approval_token=token,
        confirm_apply=True,
        eventkit_runner=_reminders_runner,
    )
    missing_confirmation = apply_reminder_change(
        "complete",
        handle=handle,
        expected_title="Synthetic runtime reminder",
        expected_completed=False,
        approval_token=token,
        eventkit_runner=_reminders_runner,
    )
    completed_search = search_reminders_eventkit(
        "completed runtime",
        eventkit_runner=_completed_reminders_runner,
    )
    completed_handle = completed_search["results"][0]["handle"]
